export class TokenBucketRateLimiter {
  private capacity: number;
  private fillRatePerSec: number;
  private tokens: number;
  private lastUpdated: number;

  constructor(capacity: number, fillRatePerSec: number) {
    this.capacity = capacity;
    this.fillRatePerSec = fillRatePerSec;
    this.tokens = capacity;
    this.lastUpdated = Date.now();
  }

  public async acquire(cost: number = 1): Promise<boolean> {
    this.refill();
    if (this.tokens >= cost) {
      this.tokens -= cost;
      return true;
    }
    return false;
  }

  private refill(): void {
    const now = Date.now();
    const deltaSec = (now - this.lastUpdated) / 1000;
    this.tokens = Math.min(this.capacity, this.tokens + deltaSec * this.fillRatePerSec);
    this.lastUpdated = now;
  }
}
